import{_ as a,o as r,c as t,a4 as s}from"./chunks/framework.9tZL7ZIQ.js";const m=JSON.parse('{"title":"艾伦·弗里德曼","description":"","frontmatter":{"title":"艾伦·弗里德曼","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/艾伦·弗里德曼.md","filePath":"04_people/艾伦·弗里德曼.md"}'),i={name:"04_people/艾伦·弗里德曼.md"};function o(l,e,n,h,_,c){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="艾伦·弗里德曼" tabindex="-1">艾伦·弗里德曼 <a class="header-anchor" href="#艾伦·弗里德曼" aria-label="Permalink to &quot;艾伦·弗里德曼&quot;">​</a></h1><ul><li><strong>角色职位</strong>：Borsheim&#39;s 管理层成员</li><li><strong>与巴菲特关系</strong>：艾克·弗里德曼之子，父子共同经营伯克希尔旗下珠宝旗舰</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>艾伦·弗里德曼是Borsheim&#39;s珠宝店的管理层成员，也是CEO艾克·弗里德曼的儿子。弗里德曼家族与伯克希尔的合作关系堪称商业传承的典范——父亲艾克奠定了Borsheim&#39;s在伯克希尔体系中的坚实地位，儿子艾伦随后加入管理层，延续了家族的经营传统。</p><p>在Borsheim&#39;s的管理工作中，艾伦·弗里德曼负责日常运营的多个关键环节，与父亲一起维护着这家珠宝店的卓越声誉。伯克希尔的股东们对Borsheim&#39;s怀有特殊的情感，而艾伦作为新一代管理者，在继承传统的同时也为这家传奇珠宝店注入了新的活力。</p><p>Borsheim&#39;s在股东大会期间的表现尤其引人注目，每逢伯克希尔年会召开，这家小小的珠宝店便会迎来世界各地朝圣般的投资者，艾伦·弗里德曼在其中承担着不可替代的角色。父子接力、共同服务于同一家伯克希尔旗下企业，这种稳定性正是巴菲特最为看重的品质之一。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1989年</strong>：Borsheim&#39;s被伯克希尔收购，艾伦随父加入管理层</li><li><strong>1990-2000年代</strong>：与父亲艾克共同管理Borsheim&#39;s日常运营</li><li><strong>21世纪</strong>：继续担任Borsheim&#39;s管理职务，传承家族经营</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=Friedman&#39;s Inc.">1988年：完整翻译|/01_letters/1988年/翻译</a></li><li><a href="/search?q=Friedman&#39;s Inc.收购完成">1989年：完整翻译|/01_letters/1989年/翻译</a></li><li><a href="/search?q=Friedman&#39;s Inc.经营">1990年：完整翻译|/01_letters/1990年/翻译</a></li></ul>',11)])])}const p=a(i,[["render",o]]);export{m as __pageData,p as default};
